'use strict';
(()=>{
const host=document.getElementById('universalApp'),note=document.getElementById('uMessage');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=id=>document.getElementById(id),lines=x=>String(x||'').split('\n').map(x=>x.trim()).filter(Boolean);
const api=async(url,method='GET',d)=>{let r=await fetch(url,{method,headers:d?{'Content-Type':'application/json'}:{},body:d?JSON.stringify(d):undefined}),v=await r.json();if(!r.ok)throw Error(typeof v.detail==='string'?v.detail:'تعذر تنفيذ الطلب');return v};
const act=fn=>async ev=>{ev?.preventDefault();const target=ev?.currentTarget,button=target?.tagName==='FORM'?target.querySelector('button:not([type=button])'):target;if(button?.tagName==='BUTTON')button.disabled=true;try{note.textContent='جارٍ التنفيذ…';await fn();note.textContent='تم بنجاح'}catch(e){note.textContent=e.message}finally{if(button?.tagName==='BUTTON')button.disabled=false}};
const field=(k,l,v='',type='text')=>`<label>${l}<input data-field="${k}" type="${type}" value="${esc(v)}"></label>`;
const area=(k,l,v='')=>`<label>${l}<textarea data-field="${k}" rows="3">${esc(v)}</textarea></label>`;
const select=(k,l,rows,v)=>`<label>${l}<select data-field="${k}">${rows.map(([a,b])=>`<option value="${esc(a)}" ${String(a)===String(v)?'selected':''}>${esc(b)}</option>`).join('')}</select></label>`;
let rows=[],jobs=[],employees=[],current=null,kind='tasks',items=[],originalActiveKeys=[],catalogVersion=null;
const newKey=()=>globalThis.crypto?.randomUUID?.()||'item_'+Date.now()+'_'+Math.random().toString(36).slice(2);
function normalize(body,k){return k==='tasks'?(body.tasks||[{...body,key:'legacy',is_active:true}]):(body.instruction_items||[{key:'legacy',text:body.instructions||'',is_active:true}])}
function readItems(){return [...get('items').querySelectorAll('[data-item]')].map(row=>{let d={key:row.dataset.item};row.querySelectorAll('[data-field]').forEach(el=>{let v=el.type==='checkbox'?el.checked:el.value;if(['week_day','month_day','estimated_minutes','due_minutes'].includes(el.dataset.field))v=Number(v);if(el.dataset.field==='completion_fields')v=lines(v);d[el.dataset.field]=v});return d})}
function renderItems(){get('items').innerHTML=items.map((x,i)=>`<fieldset data-item="${esc(x.key)}"><legend>${kind==='tasks'?'مهمة':'بند تعليمات'} ${i+1}</legend><div class="bundle-grid">${kind==='instructions'?area('text','نص البند (يمكن كتابة عدة أسطر)',x.text):field('title','عنوان المهمة',x.title)+area('instructions','تعليمات وملاحظات المهمة',x.instructions)+select('mode','الإسناد',[['individual','مهمة مستقلة لكل موظف'],['team','مهمة مشتركة']],x.mode)+select('schedule','التكرار',[['manual','يدوي'],['daily','يومي'],['weekly','أسبوعي'],['monthly','شهري']],x.schedule)+field('run_time','وقت الإنشاء',x.run_time||'09:00','time')+select('week_day','يوم الأسبوع',['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'].map((v,i)=>[i,v]),x.week_day)+field('month_day','يوم الشهر',x.month_day||1,'number')+field('due_minutes','مهلة التسليم بالدقائق',x.due_minutes||480,'number')+field('estimated_minutes','جهد مقدر بالدقائق (0 = غير محدد)',x.estimated_minutes||0,'number')+select('priority','الأولوية',['عادي','منخفضة','عالية','عاجلة'].map(v=>[v,v]),x.priority)+area('completion_fields','حقول الإنجاز الاختيارية — حقل بكل سطر',(x.completion_fields||[]).join('\n'))}</div>${kind==='tasks'?`<label><input data-field="workdays_only" type="checkbox" ${x.workdays_only!==false?'checked':''}> أيام دوام الموظف فقط في التوليد التلقائي</label>`:''}<p><label><input data-field="is_active" type="checkbox" ${x.is_active!==false?'checked':''}> البند مفعّل</label> <button type="button" data-remove="${i}">حذف هذا البند من القالب</button></p></fieldset>`).join('')||'<p>القالب فارغ. اضغط إضافة بند.</p>';get('items').querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>{items=readItems();items.splice(+btn.dataset.remove,1);renderItems();get('saveNotice').textContent='الحذف لم يُحفظ بعد. حدد مصير المهام المفتوحة ثم احفظ القالب.'})}
function editor(t){current=t;kind=t?.kind||'tasks';catalogVersion=t?.version;items=t?normalize(t.body,kind):[];originalActiveKeys=items.filter(x=>x.is_active!==false).map(x=>x.key);get('editor').innerHTML=`<form id="bundleForm" class="bundle-panel"><h2>${t?'تعديل القالب':'قالب جديد'}</h2><label>اسم القالب<input id="templateName" maxlength="100" value="${esc(t?.name)}" required></label><label>النوع<select id="templateKind" ${t?'disabled':''}><option value="tasks" ${kind==='tasks'?'selected':''}>مجموعة مهام</option><option value="instructions" ${kind==='instructions'?'selected':''}>مجموعة تعليمات</option></select></label><div id="commonBlock"><label>تعليمات عامة تُرفق بكل مهام هذا القالب<textarea id="commonInstructions" rows="3">${esc(t?.body.tasks?t.body.instructions:'')}</textarea></label></div><div id="items"></div><button type="button" id="addItem">＋ إضافة بند</button><p><label><input id="templateActive" type="checkbox" ${!t||t.is_active?'checked':''}> القالب مفعّل</label></p>${t?'<label>عند حذف أو تعطيل بنود لها مهام مفتوحة<select id="openPolicy"><option value="">اختر إجراءً عند الحاجة</option><option value="keep">إبقاء المهام المفتوحة كما هي</option><option value="cancel">إلغاء المهام المفتوحة التابعة للبنود المتأثرة فقط</option></select></label>':''}<p id="saveNotice" role="status">التعديلات تُحفظ كإصدار جديد؛ الإنجازات السابقة محفوظة.</p><button>حفظ القالب</button></form><section id="links"></section><section id="preview"></section>`;
const showKind=()=>{get('commonBlock').hidden=kind!=='tasks';get('addItem').textContent=kind==='tasks'?'＋ إضافة مهمة':'＋ إضافة بند تعليمات';renderItems()};showKind();get('templateKind').onchange=()=>{let chosen=get('templateKind').value;if(items.length&&!confirm('تغيير النوع سيفرغ البنود غير المحفوظة. متابعة؟')){get('templateKind').value=kind;return}kind=chosen;items=[];showKind()};get('addItem').onclick=()=>{items=readItems();items.push({key:newKey(),is_active:true});renderItems()};
get('bundleForm').onsubmit=act(async()=>{items=readItems();const body=kind==='tasks'?{tasks:items,instructions:get('commonInstructions').value}:{instruction_items:items};const d={name:get('templateName').value,kind,body,is_active:get('templateActive').checked?1:0,expected_version:catalogVersion,open_policy:get('openPolicy')?.value};const removed=originalActiveKeys.some(key=>!items.some(x=>x.key===key&&x.is_active));if(t&&kind==='tasks'&&(removed||!d.is_active)){let p=await api('/api/templates/'+t.id+'/preview');if(p.open_tasks.length&&!d.open_policy)throw Error('اختر إبقاء المهام المفتوحة أو إلغاءها قبل الحفظ');if(d.open_policy==='cancel'&&!confirm('إلغاء المهام المفتوحة التابعة للبنود المتأثرة؟ الإنجازات المكتملة لن تتغير.'))return}let r=await api('/api/templates'+(t?'/'+t.id:''),t?'PATCH':'POST',d);await load(t?.id||r.id)});
if(t){get('links').innerHTML=`<h3>ربط المجموعة مرة واحدة</h3><form id="linkForm"><p>بالمسميات الوظيفية</p>${jobs.map(x=>link('job',x,t)).join('')}<p>بالموظفين مباشرة</p>${employees.map(x=>link('employee',x,t)).join('')}<p><button>حفظ الربط</button> <button type="button" id="previewBtn">معاينة الموظفين والمهام المفتوحة</button>${kind==='tasks'?' <button type="button" id="generateBtn">إنشاء جميع مهام القالب الآن</button>':''}</p></form>`;
get('linkForm').onsubmit=act(async()=>{let f=new FormData(get('linkForm'));await api('/api/templates/'+t.id+'/links','PUT',{job_ids:f.getAll('job').map(Number),employee_ids:f.getAll('employee').map(Number)})});
if(get('generateBtn'))get('generateBtn').onclick=act(async()=>{if(!confirm('إنشاء دفعة فورية من كل البنود المفعلة للموظفين المرتبطين؟'))return;let r=await api('/api/templates/'+t.id+'/generate','POST',{request_key:newKey()});alert('أُنشئت '+r.task_ids.length+' مهمة')});
get('previewBtn').onclick=act(async()=>{let p=await api('/api/templates/'+t.id+'/preview');get('preview').innerHTML=`<h3>الموظفون</h3>${p.employees.map(e=>`<p>${esc(e.name)} <button data-override="${e.id}">تخصيص</button></p>`).join('')||'لا يوجد موظفون مشمولون'}<h3>المهام المفتوحة</h3><p>التحديث الصريح يحفظ المواعيد والمشاركين ويتجاوز المهام المخصصة أو التي حُذف بندها.</p>${p.open_tasks.map(x=>`<label style="display:block"><input name="openTask" type="checkbox" value="${x.id}" ${x.customized?'disabled':''}>${esc(x.title)} · ${esc(x.status)} · إصدار ${x.version}</label>`).join('')}${kind==='tasks'?'<button id="applyOpen">تحديث المهام المختارة إلى إصدار القالب الحالي</button>':''}`;
if(get('applyOpen'))get('applyOpen').onclick=act(async()=>{let ids=[...get('preview').querySelectorAll('[name=openTask]:checked')].map(x=>+x.value);if(!ids.length||!confirm('تحديث '+ids.length+' مهمة؟'))return;let r=await api('/api/templates/'+t.id+'/apply-open','POST',{task_ids:ids,expected_version:p.template.version});alert('تم تحديث '+r.changed.length+' وتجاوز '+r.skipped.length)});
get('preview').querySelectorAll('[data-override]').forEach(btn=>btn.onclick=act(async()=>{let e=p.employees.find(x=>x.id===+btn.dataset.override);if(kind==='instructions'){let value=prompt('تعليمات خاصة بهذا الموظف (عدة أسطر)',e.body.instructions);if(value!==null)await api('/api/templates/'+t.id+'/employee/'+e.id,'PUT',{instructions:value});return}let choices=normalize(e.body,'tasks').filter(x=>x.mode!=='team'),index=prompt(choices.map((x,i)=>(i+1)+'. '+x.title).join('\n')+'\nاختر رقم المهمة لتخصيصها، أو اتركه فارغاً للإلغاء');if(!index)return;let item=choices[Number(index)-1];if(!item)throw Error('رقم غير صحيح');let value=prompt('تعليمات هذه المهمة لهذا الموظف',item.instructions);if(value===null)return;let fields=prompt('حقول الإنجاز — افصل بفاصلة عربية «،»',(item.completion_fields||[]).join('،'));if(fields===null)return;await api('/api/templates/'+t.id+'/employee/'+e.id+'/items/'+item.key,'PUT',{instructions:value,completion_fields:fields.split('،').map(x=>x.trim()).filter(Boolean)});}));
});}get('editor').scrollIntoView({behavior:'smooth'})}
function link(k,x,t){return `<label style="display:inline-block;margin:8px"><input type="checkbox" name="${k}" value="${x.id}" ${t.links.some(l=>l.target_kind===k&&l.target_id===x.id)?'checked':''}>${esc(x.name)}${x.is_active?'':' (معطل)'}</label>`}
async function load(editId){[rows,employees,jobs]=await Promise.all([api('/api/templates'),api('/api/employees?all=1'),api('/api/bim-job-profiles').then(x=>x.jobs)]);host.innerHTML=`<p>قالب واحد يضم عدة مهام أو بنود تعليمات؛ تربطه بالمسمى أو الموظفين مرة واحدة. تعطيل البند يوقف توليده، وحذفه يزيله من الإصدار الجديد مع حفظ التاريخ.</p><p><button id="newTemplate">قالب جديد</button> <a href="/record-management?entity=templates">المحذوفات والاستعادة</a></p><div id="editor"></div>${rows.map(t=>`<article class="bundle-panel"><b>${esc(t.name)}</b> · ${t.kind==='tasks'?'مهام':'تعليمات'} · ${normalize(t.body,t.kind).length} بند · الإصدار ${t.version} · ${t.is_active?'مفعّل':'معطل'} <button data-edit="${t.id}">تعديل وربط</button> <button data-action="${t.is_active?'disable':'enable'}" data-id="${t.id}">${t.is_active?'تعطيل':'تفعيل'}</button> <button data-action="delete" data-id="${t.id}">حذف القالب</button></article>`).join('')}`;get('newTemplate').onclick=()=>editor(null);host.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(rows.find(t=>t.id===+b.dataset.edit)));host.querySelectorAll('[data-action]').forEach(b=>b.onclick=act(async()=>{if(await window.recordAction('templates',+b.dataset.id,b.dataset.action))await load()}));if(editId)editor(rows.find(x=>x.id===editId))}
act(load)();
})();
